import { useCallback, useMemo } from 'react';

import { type RowClickEvent, TableDataType } from 'components/TableComponent';
import { useDataRefreshForTab } from 'contexts/DataRefreshModal/useDataRefreshForTab';

import { AudiencePlanningError } from '../../constants';
import { useDefinitionInteractiveAudience } from '../../hooks';
import { BrandAudience, ParticipationBreakdown } from './components';
import {
  getDemographicGroupOptions,
  resolveRowSelection,
} from './components/ParticipationBreakdown/utils';
import { DefinitionContainer } from './Definition.styles';

interface DefinitionProps {
  dataTestId?: string;
  breakdownData?: TableDataType | null;
  isLoading?: boolean;
  error?: Error | null;
}

export const Definition = ({
  dataTestId,
  breakdownData,
  isLoading,
  error,
}: DefinitionProps) => {
  useDataRefreshForTab('Audience Planning - Definition');

  const groupOptions = useMemo(
    () => getDemographicGroupOptions(breakdownData ?? null),
    [breakdownData],
  );

  const {
    activeAudience,
    selection,
    highlightedItems,
    isFetching,
    error: fetchError,
    hasResult,
    percentage,
    selectAudience,
    toggleRow,
  } = useDefinitionInteractiveAudience(groupOptions);

  const isCompetitorWithoutData =
    error?.message === AudiencePlanningError.CompetitorWithoutData;

  const handleRowClick = useCallback(
    (event: RowClickEvent) => {
      const resolved = resolveRowSelection(breakdownData ?? null, event);
      if (resolved) toggleRow(resolved);
    },
    [breakdownData, toggleRow],
  );

  return (
    <DefinitionContainer>
      <BrandAudience
        isLoading={isLoading ?? false}
        hasData={!!breakdownData}
        error={isCompetitorWithoutData ? null : (error ?? null)}
        activeAudience={activeAudience}
        selection={selection}
        percentage={percentage}
        isFetching={isFetching}
        fetchError={fetchError}
        hasResult={hasResult}
        onSelectAudience={selectAudience}
        dataTestId={`${dataTestId}-brand-audience`}
      />
      <ParticipationBreakdown
        data={breakdownData}
        dataTestId={`${dataTestId}-participation-breakdown`}
        isLoading={isLoading ?? false}
        highlightedItems={highlightedItems}
        error={error ?? null}
        interactiveMode={activeAudience !== null}
        onRowClick={handleRowClick}
      />
    </DefinitionContainer>
  );
};
